export function getRecipeById(id: string): MasterRecipe | undefined {
  return MASTER_RECIPES.find((r) => r.id === id);
}

export function getRecipesByCategory(category: string): MasterRecipe[] {
  return MASTER_RECIPES.filter((r) => r.category === category);
}
